using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using VehicleRental.Domain.Entities;
using VehicleRental.Infrastructure.Identity;

namespace VehicleRental.Infrastructure.Persistence.Configurations;

// Phase 14A-3, the "expand" step of ADR 007: structure only. Nothing in the running application reads or writes any of
// this yet. Conventions follow the existing tables: PascalCase names, Guid keys generated by the domain, enums stored
// as text, and database checks that back up the domain rules.

internal sealed class CompanyConfiguration : IEntityTypeConfiguration<Company>
{
    public const string SlugIndex = "UX_Companies_Slug";

    public void Configure(EntityTypeBuilder<Company> builder)
    {
        builder.ToTable("Companies", table =>
        {
            // The same rule as Company.ValidateSlug (reserved names stay an application rule: that list will change).
            table.HasCheckConstraint(
                "CK_Companies_Slug_Format",
                "\"Slug\" ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(\"Slug\") BETWEEN 3 AND 63");
            table.HasCheckConstraint("CK_Companies_Name_NotBlank", "char_length(btrim(\"Name\")) > 0");
            table.HasCheckConstraint("CK_Companies_TimeZoneId_NotBlank", "char_length(btrim(\"TimeZoneId\")) > 0");
            table.HasCheckConstraint(
                "CK_Companies_Status_Known",
                "\"Status\" IN ('PendingReview', 'Active', 'Suspended')");

            // A company is public only after approval, and an unapproved one is always PendingReview or rejected.
            table.HasCheckConstraint(
                "CK_Companies_ActiveIsApproved",
                "\"Status\" <> 'Active' OR \"ApprovedAt\" IS NOT NULL");
            table.HasCheckConstraint(
                "CK_Companies_PendingIsNotApproved",
                "\"Status\" <> 'PendingReview' OR \"ApprovedAt\" IS NULL");
        });

        builder.HasKey(c => c.Id);
        builder.Property(c => c.Id).ValueGeneratedNever();

        // The company's web address. The "C" collation compares bytes, like the other business keys.
        builder.Property(c => c.Slug)
            .IsRequired()
            .HasMaxLength(Company.SlugMaxLength)
            .UseCollation("C");
        builder.HasIndex(c => c.Slug).IsUnique().HasDatabaseName(SlugIndex);

        builder.Property(c => c.Name).IsRequired().HasMaxLength(Company.NameMaxLength);
        builder.Property(c => c.Status).HasConversion<string>().HasMaxLength(20).IsRequired();
        builder.Property(c => c.TimeZoneId).IsRequired().HasMaxLength(Company.TimeZoneIdMaxLength);
        builder.Property(c => c.CreatedAt).IsRequired();
        builder.Property(c => c.ApprovedAt);

        builder.Property<uint>("xmin").IsRowVersion();
    }
}

internal sealed class CompanyMembershipConfiguration : IEntityTypeConfiguration<CompanyMembership>
{
    public const string OneRowPerUserIndex = "UX_CompanyMemberships_CompanyId_UserId";

    public void Configure(EntityTypeBuilder<CompanyMembership> builder)
    {
        builder.ToTable("CompanyMemberships", table =>
        {
            table.HasCheckConstraint("CK_CompanyMemberships_Role_Known", "\"Role\" IN ('Owner', 'Staff')");
            table.HasCheckConstraint("CK_CompanyMemberships_Status_Known", "\"Status\" IN ('Active', 'Removed')");
        });

        builder.HasKey(m => m.Id);
        builder.Property(m => m.Id).ValueGeneratedNever();

        // Companies and logins are never deleted while memberships exist: access history stays.
        builder.HasOne<Company>()
            .WithMany()
            .HasForeignKey(m => m.CompanyId)
            .IsRequired()
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasOne<ApplicationUser>()
            .WithMany()
            .HasForeignKey(m => m.UserId)
            .IsRequired()
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasOne<ApplicationUser>()
            .WithMany()
            .HasForeignKey(m => m.CreatedByUserId)
            .IsRequired(false)
            .OnDelete(DeleteBehavior.Restrict);

        builder.Property(m => m.Role).HasConversion<string>().HasMaxLength(20).IsRequired();
        builder.Property(m => m.Status).HasConversion<string>().HasMaxLength(20).IsRequired();
        builder.Property(m => m.CreatedAt).IsRequired();

        // One row per company and user; it also serves "who works for this company".
        builder.HasIndex(m => new { m.CompanyId, m.UserId }).IsUnique().HasDatabaseName(OneRowPerUserIndex);

        // "Which companies can this user act for?", asked on every management request.
        builder.HasIndex(m => new { m.UserId, m.Status }).HasDatabaseName("IX_CompanyMemberships_UserId_Status");

        // The "at least one active owner" rule will look owners up by company.
        builder.HasIndex(m => m.CompanyId)
            .HasFilter("\"Role\" = 'Owner' AND \"Status\" = 'Active'")
            .HasDatabaseName("IX_CompanyMemberships_ActiveOwners");
    }
}

internal sealed class CompanyCustomerConfiguration : IEntityTypeConfiguration<CompanyCustomer>
{
    public const string NumberIndex = "UX_CompanyCustomers_CompanyId_CustomerNumber";
    public const string PersonIndex = "UX_CompanyCustomers_CompanyId_CustomerId";
    public const string ForeignKeyTargetIndex = "UX_CompanyCustomers_CompanyId_Id";

    public void Configure(EntityTypeBuilder<CompanyCustomer> builder)
    {
        builder.ToTable("CompanyCustomers");

        builder.HasKey(c => c.Id);
        builder.Property(c => c.Id).ValueGeneratedNever();

        builder.HasOne<Company>()
            .WithMany()
            .HasForeignKey(c => c.CompanyId)
            .IsRequired()
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasOne<Customer>()
            .WithMany()
            .HasForeignKey(c => c.CustomerId)
            .IsRequired()
            .OnDelete(DeleteBehavior.Restrict);

        builder.Property(c => c.CustomerNumber)
            .IsRequired()
            .HasMaxLength(Customer.CustomerNumberMaxLength)
            .UseCollation("C");
        builder.Property(c => c.CreatedAt).IsRequired();

        // The business key is unique per company, not across the platform: two companies may use the same number.
        builder.HasIndex(c => new { c.CompanyId, c.CustomerNumber }).IsUnique().HasDatabaseName(NumberIndex);

        // A person has one link (and so one number) per company.
        builder.HasIndex(c => new { c.CompanyId, c.CustomerId }).IsUnique().HasDatabaseName(PersonIndex);

        // The target the contract step's composite foreign keys (CompanyId, CompanyCustomerId) will point at.
        builder.HasIndex(c => new { c.CompanyId, c.Id }).IsUnique().HasDatabaseName(ForeignKeyTargetIndex);

        // "Which companies know this customer?" (the customer's own view of their bookings).
        builder.HasIndex(c => c.CustomerId).HasDatabaseName("IX_CompanyCustomers_CustomerId");
    }
}

/// <summary>
/// The nullable tenant columns on the existing tables, as EF shadow properties: the domain classes, the DTOs and the
/// API do not know about them. They stay NULL until the backfill phase. Deliberately NOT added in this step: NOT NULL,
/// composite foreign keys, per-company unique keys, Row-Level Security, and indexes for tenant queries (nothing
/// queries by company yet; each is added by the later step that needs it).
/// </summary>
internal static class TenancyColumns
{
    public const string CompanyId = "CompanyId";
    public const string CompanyCustomerId = "CompanyCustomerId";

    public static void AddCompanyId<T>(EntityTypeBuilder<T> builder, string table)
        where T : class
    {
        builder.Property<Guid?>(CompanyId);

        builder.HasOne<Company>()
            .WithMany()
            .HasForeignKey(CompanyId)
            .IsRequired(false)
            .OnDelete(DeleteBehavior.Restrict)
            .HasConstraintName($"FK_{table}_Companies_CompanyId");
    }

    /// <summary>
    /// Added as a plain column now; its composite foreign key (CompanyId, CompanyCustomerId) needs the backfill first
    /// and belongs to the contract step.
    /// </summary>
    public static void AddCompanyCustomerId<T>(EntityTypeBuilder<T> builder)
        where T : class
    {
        builder.Property<Guid?>(CompanyCustomerId);
    }
}

internal sealed class VehicleTenancyConfiguration : IEntityTypeConfiguration<Vehicle>
{
    public const string ForeignKeyTargetIndex = "UX_Vehicles_CompanyId_Id";

    public void Configure(EntityTypeBuilder<Vehicle> builder)
    {
        TenancyColumns.AddCompanyId(builder, "Vehicles");

        // The target of the contract step's composite foreign keys, e.g. Reservations (CompanyId, VehicleId). Id is
        // already unique, so this can never reject an existing row, and while CompanyId is NULL it constrains nothing.
        builder.HasIndex(TenancyColumns.CompanyId, nameof(Vehicle.Id)).IsUnique().HasDatabaseName(ForeignKeyTargetIndex);
    }
}

internal sealed class ReservationTenancyConfiguration : IEntityTypeConfiguration<Reservation>
{
    public void Configure(EntityTypeBuilder<Reservation> builder)
    {
        TenancyColumns.AddCompanyId(builder, "Reservations");
        TenancyColumns.AddCompanyCustomerId(builder);
    }
}

internal sealed class RentalTenancyConfiguration : IEntityTypeConfiguration<Rental>
{
    public void Configure(EntityTypeBuilder<Rental> builder)
    {
        TenancyColumns.AddCompanyId(builder, "Rentals");
        TenancyColumns.AddCompanyCustomerId(builder);
    }
}
